616	+const FNV_OFFSET = 0xcbf29ce484222325n;
617	+const FNV_PRIME = 0x100000001b3n;
618	+const MASK_64 = 0xffffffffffffffffn;
619	+
620	+/** 64-bit FNV-1a over the UTF-16 code units of a string, as 16 hex digits. */
621	+function fnv1a64(text: string): string {
622	+  let hash = FNV_OFFSET;
623	+  for (let index = 0; index < text.length; index++) {
624	+    const unit = text.charCodeAt(index);
625	+    hash = ((hash ^ BigInt(unit & 0xff)) * FNV_PRIME) & MASK_64;
626	+    hash = ((hash ^ BigInt(unit >>> 8)) * FNV_PRIME) & MASK_64;
627	+  }
628	+  return hash.toString(16).padStart(16, "0");
629	+}
